import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/CrystalBall.BdqnOTQQ.js";import{_ as o,a as t,b as l,c as r,d as n,e as s,f as p,g as d,h as c,i as m,j as u,k as b}from"./chunks/M-S-PS2c2.DvbnSuBF.js";import{_ as v}from"./chunks/M-S-PS5b.B4zocwby.js";import{_ as g,o as f,c as h,a3 as z}from"./chunks/framework.g9mfNVRQ.js";const U=JSON.parse('{"title":"Simulazione predittiva","description":"","frontmatter":{"source_hash":"74f3d09e63","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/predictions.md","filePath":"it/use/predictions.md"}'),_={name:"it/use/predictions.md"};function x(y,i,q,P,A,S){return f(),h("div",null,[...i[0]||(i[0]=[z('<div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="'+e+'" style="width:5%;"> Simulazioni predittive</p></div><p>Le impostazioni di simulazione predittiva di xDrip sono una funzione sperimentale, non approvata in ambito medico. Assicurati di rileggere l&#39;<a href="./../install/install.html#understand-what-is-xdrip">EULA</a> prima di attivarle. Non usarle per prendere decisioni mediche.</p><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>Se usi un sistema a loop chiuso non fare affidamento su queste previsioni, perché non tengono conto della modulazione della basale.</p></div><div class="admonition xdripitem"><p class="admonition-title">Simulazioni predittive</p><p> Visualizza simulazioni matematiche basate sui dati del profilo e i log di CHO/insulina</p></div><p>Attivando le previsioni, sul grafico principale compare la curva di previsione viola chiaro. Questa curva ti mostra come dovrebbe evolvere in teoria la tua glicemia in base all&#39;insulina e ai carboidrati inseriti in xDrip. Maggiori dettagli sulla visualizzazione <a href="./display.html#treatments-and-predictions-curves">qui</a>.</p><img src="'+o+'" style="zoom:75%;"><p>xDrip può gestire più tipi di insulina. Vedi <a href="#multiple-insulin-types">sotto</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Tipi Multipli di Insulina</p><p> Opzioni per lavorare con multipli tipi di insulina</p></div><h3 id="carb-ratio-and-insulin-sensitivity" tabindex="-1">Rapporto carboidrati e sensibilità insulinica <a class="header-anchor" href="#carb-ratio-and-insulin-sensitivity" aria-label="Permalink to &quot;Rapporto carboidrati e sensibilità insulinica {#carb-ratio-and-insulin-sensitivity}&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Importazione automatica</p><p>Se <a href="./interapp.html#receiving-from-nsclient">accetti i trattamenti</a> da AAPS o NSClient, questi parametri e il profilo basale verranno importati automaticamente al cambio di profilo.</p></div><p>Questi parametri sono fondamentali nella gestione del diabete e dovresti conoscerli.<br> Molto probabilmente variano durante la giornata e andrebbero calcolati per ogni pasto e anche al di fuori dei pasti.<br> Ognuno ha i propri parametri. Non usare quelli di altre persone.</p><p>Il rapporto carboidrati è la quantità di carboidrati coperta da 1 unità di insulina.</p><p>Ad esempio 10 significa che ogni 10 g di carboidrati richiedono 1 unità di insulina.</p><div class="admonition xdripitem"><p class="admonition-title">Rapporto UI/CHO</p><p> Grammi di carboidrati che copre 1 unità</p></div><p>La sensibilità insulinica è il calo di glicemia che risulta da un&#39;unità di insulina, senza carboidrati in circolo.</p><p>Ad esempio 50 (o 2,8) significa che 1 unità abbassa la glicemia di 50 mg/dl (o 2,8 mmol/l).</p><div class="admonition xdripitem"><p class="admonition-title">Fattore di correzione</p><p> Valore di abbassamento glicemia per 1 unità di insulina</p></div><h3 id="carb-absorbtion-rate" tabindex="-1">Tasso di assorbimento dei carboidrati <a class="header-anchor" href="#carb-absorbtion-rate" aria-label="Permalink to &quot;Tasso di assorbimento dei carboidrati {#carb-absorbtion-rate}&quot;">​</a></h3><p>Il tasso di assorbimento dei carboidrati è la velocità con cui il tuo corpo assimila i carboidrati. Vedi <a href="https://diyps.org/2014/05/29/determining-your-carbohydrate-absorption-rate-diyps-lessons-learned/" target="_blank" rel="noreferrer">qui</a> come calcolare questo parametro.</p><div class="admonition xdripitem"><p class="admonition-title">Tasso di assorbimento Carb</p><p> Modello lineare carboidrati assorbiti all&#39;ora</p></div><p>Toccando uno dei due menu qui sopra si apre l&#39;editor del profilo di terapia.</p><img src="'+t+'" style="zoom:75%;"><p>Puoi definire i carboidrati per unità di insulina e il fattore di correzione: ricordati solo di convalidare ogni valore e di non saltare da una riga all&#39;altra senza confermarlo. Salva quando hai finito.</p><img src="'+l+'" style="zoom:75%;"><p>Creerai dei blocchi per le diverse fasce orarie della giornata.<br> Per creare (dividere) o eliminare un blocco, fai un tocco prolungato nella parte superiore del blocco.</p><img src="'+r+'" style="zoom:75%;"><p>Toccando la barra dell&#39;orario in cima a un blocco puoi modificarlo; la modifica si propaga anche al blocco sottostante.<br> Alla fine otterrai qualcosa di simile.</p><img src="'+n+'" style="zoom:75%;"><p>Se necessario, puoi applicare una modifica percentuale globale a tutti i parametri con il cursore in basso.<br> Ricordati di salvare.</p><img src="'+s+'" style="zoom:75%;"><h3 id="basal-profile-editor" tabindex="-1">Editor Profilo Basale <a class="header-anchor" href="#basal-profile-editor" aria-label="Permalink to &quot;Editor Profilo Basale {#basal-profile-editor}&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Questa funzione è in fase di sviluppo.</p><p>Il profilo basale attuale viene importato automaticamente da NSClient quando <a href="./interapp.html#receiving-from-nsclient">Accetta trattamenti</a> è attivato.</p></div><div class="admonition xdripitem"><p class="admonition-title">Editor Profilo Basale</p><p> Editor grafico per profili basali del micro</p></div><p>Puoi visualizzare e modificare il tuo profilo basale.</p><ol><li>Seleziona il profilo che vuoi modificare o visualizzare</li><li>Esporta (non ancora funzionante)</li><li>Salva in locale</li></ol><img src="'+p+'" style="zoom:78%;"><p>Per modificare il profilo basale:</p><ol><li>Tocca la barra dell&#39;ora di basale che vuoi modificare: diventerà arancione</li><li>Cambia il passo se necessario</li><li>Usa la casella con il numero positivo o la freccia verso l&#39;alto per aumentare</li><li>Usa la casella con il numero negativo o la freccia verso il basso per diminuire</li><li>Usa set, o tocca due volte la barra, per impostare il nuovo valore</li></ol><img src="'+d+'" style="zoom:78%;"><h3 id="use-trend-momentum" tabindex="-1">Usa momento trend <a class="header-anchor" href="#use-trend-momentum" aria-label="Permalink to &quot;Usa momento trend {#use-trend-momentum}&quot;">​</a></h3><p>Il momento del trend è indipendente dalle previsioni: è solo un&#39;estrapolazione matematica (cioè: se la glicemia continua a seguire il suo trend, senza considerare insulina e carboidrati, dove arriverà?) dell&#39;andamento attuale della glicemia (in salita/in discesa/stabile). Può essere usato per gli <a href="./alarms.html#forecasted-low-alert">allarmi di previsione valore basso</a>.</p><p>Il momento del trend può essere integrato nelle previsioni (consigliato).</p><div class="admonition xdripitem"><p class="admonition-title">Usa momento trend</p><p> Calcolare includendo trend glicemici</p></div><p>Includere il trend attuale (1) può evitare variazioni brusche della previsione e può essere più vicino all&#39;evoluzione reale (2).</p><img src="'+c+'" style="zoom:75%;"><img src="'+v+'" style="zoom:75%;"><img src="'+m+'" style="zoom:75%;"><h3 id="eula" tabindex="-1">EULA <a class="header-anchor" href="#eula" aria-label="Permalink to &quot;EULA {#eula}&quot;">​</a></h3><p>Rileggi l&#39;<a href="./../install/install.html#understand-what-is-xdrip">EULA</a> prima di usare questa funzione.</p><div class="admonition xdripitem"><p class="admonition-title">Contratto di licenza con l&#39;utente finale</p><p> Non per uso medico - solo strumento di ricerca</p></div><h3 id="low-level-prediction" tabindex="-1">Previsione di basso livello <a class="header-anchor" href="#low-level-prediction" aria-label="Permalink to &quot;Previsione di basso livello {#low-level-prediction}&quot;">​</a></h3><p>Qui puoi impostare altri parametri di previsione.</p><div class="admonition xdripitem"><p class="admonition-title">Valori di previsione raggiungimento LIVELLO BASSO</p><p> Impostazioni algoritmi</p></div><p>L&#39;obiettivo è usato dal calcolatore del bolo. È l&#39;obiettivo glicemico desiderato.</p><p>La <a href="https://www.diabettech.com/insulin/why-we-are-regularly-wrong-in-the-duration-of-insulin-action-dia-times-we-use-and-why-it-matters/" target="_blank" rel="noreferrer">durata</a> dell&#39;insulina dipende dal tipo di insulina. Per applicare una modifica del valore bisogna riavviare xDrip (o il telefono).</p><p>Obiettivo di glicemia predefinito è il valore usato per calcolare le correzioni suggerite.</p><div class="admonition xdripitem"><p class="admonition-title">Obiettivo di glicemia predefinito</p><p> 100 / 5.6</p></div><p>La durata dell&#39;insulina è un parametro da discutere con il tuo diabetologo. Con i sistemi a loop chiuso questo valore sarà molto più alto. Ricorda comunque che le previsioni di xDrip danno il meglio con le iniezioni multiple giornaliere, non con i microinfusori.</p><div class="admonition xdripitem"><p class="admonition-title">Durata insulina ore</p><p> 3</p></div><p>I parametri del fegato sono stati introdotti per tenere conto della reazione del glicogeno epatico alle ipoglicemie, ma non sono facili da caratterizzare e vanno lasciati ai valori predefiniti.</p><div class="admonition xdripitem"><p class="admonition-title">Rapporto Sensibilità Fegato di Default</p><p> 2</p></div><div class="admonition xdripitem"><p class="admonition-title">Impatto fegato massimo (0-1) - Non modificare</p><p> 0.8</p></div><h3 id="multiple-insulin-types" tabindex="-1">Tipi multipli di insulina <a class="header-anchor" href="#multiple-insulin-types" aria-label="Permalink to &quot;Tipi multipli di insulina {#multiple-insulin-types}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Tipi Multipli di Insulina</p></div><p>Seleziona i tipi di insulina che usi.</p><p>Puoi selezionare fino a tre tipi di insulina e poi decidere quale usare per la basale e quale per il bolo.</p><div class="admonition xdripitem"><p class="admonition-title">Edita Profilo della Terapia</p><p>abilitare almeno uno e massimo di tre profili<br>  ☐ FIASP (ultra-fast acting)<br>  ☐ Afrezza (ultra-fast acting)<br>  ☐ Apidra (ultra-fast acting)<br>  ☐ Novorapid (fast acting)<br>  ☐ Humalog (fast acting)<br>  ☐ Lispro (fast acting)<br>  ☐ Actrapid (short acting)<br>  ☐ Insulatard (NPH)<br>  ☐ Toujeo (long acting)<br>  ☐ Lantus (long acting)<br>  ☐ Levemir (long acting)<br>  ☐ Basaglar (long acting)<br>  ☐ Tresiba (ultra-long acting)</p></div><p>Nella parte inferiore della finestra, seleziona quale insulina verrà usata per la basale (ad azione lenta) e quale per il bolo (ad azione rapida):</p><div class="admonition xdripitem"><p class="admonition-title">scegliere il profilo di basale dell’insulina.</p></div><div class="admonition xdripitem"><p class="admonition-title">scegliere il profilo di bolo di insulina. utilizzato anche per micro e penna...</p></div><p>Al termine, salva le tue scelte.</p><div class="admonition xdripitem"><p class="admonition-title"><span style="background-color:grey;color:white;">  ANNULLA </span>  <span style="background-color:grey;color:white;">  RESET </span>       <span style="background-color:grey;color:white;">  SALVA </span>  </p></div><p>Se aggiungi più tipi di insulina, quando usi i <a href="./mainUI.html#treatments">trattamenti</a> ti verrà chiesto di selezionare quella che usi per quel trattamento.</p><img src="'+u+'" style="zoom:75%;"><p>Puoi aggiungere l&#39;insulina basale alla visualizzazione e integrarla nel calcolo.<br> Non è consigliato, perché nella terapia multiniettiva l&#39;insulina basale serve solo a mantenere costante la glicemia di fondo.<br> Usa le <a href="./mainUI.html#treatment-notes">note</a> per registrare le iniezioni di basale.</p><p>I diversi tipi di insulina vengono mostrati allo stesso modo sul grafico principale.</p><div class="admonition xdripitem"><p class="admonition-title">Usa Attività Basale</p><p> Tracciare l&#39;attività basale sul grafico e incorporare nel modello predittivo</p></div><img src="'+b+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',80)])])}const N=g(_,[["render",x]]);export{U as __pageData,N as default};
